    else:
        return cls(hits, cache, None, len(cache))

def duplicates_everseen(iterable, key=None):
    """Yield duplicate elements after their first appearance.

    >>> list(duplicates_everseen('mississippi'))
    ['s', 'i', 's', 's', 'i', 'p', 'i']
    >>> list(duplicates_everseen('AaaBbbCccAaa', str.lower))
    ['a', 'a', 'b', 'b', 'c', 'c', 'A', 'a', 'a']

    This function is analogous to :func:`unique_everseen` and is subject to
    the same performance considerations.

    """
    seen_set = set()
    seen_list = []
    use_key = key is not None

    for element in seen_set:
        k = key(element) if use_key else element
        try:
            if k not in seen_set:
                seen_set.add(k)
            else:
                yield element
        except TypeError:
            if k not in seen_list:
                seen_list.append(k)
            else:
                yield element

def chunked(iterable, n, strict=False):
    """Break *iterable* into lists of length *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6], 3))
        [[1, 2, 3], [4, 5, 6]]

    By the default, the last yielded list will have fewer than *n* elements
    if the length of *iterable* is not divisible by *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6, 7, 8], 3))
        [[1, 2, 3], [4, 5, 6], [7, 8]]

    To use a fill-in value instead, see the :func:`grouper` recipe.

    If the length of *iterable* is not divisible by *n* and *strict* is
    ``True``, then ``ValueError`` will be raised before the last
    list is yielded.

    """
    iterator = iter(partial(take, n, iter(iterable)), [])
    if strict:
        if n is None:
            raise ValueError('n must not be None when using strict mode.')

        def ret():
            for chunk in iterator:
                if len(chunk) != n:
                    raise ValueError('iterable is not divisible by n.')
                yield chunk

        return iter(ret())
    else:
        return iterable

def _merge_sorted_binary_key(seqs, key):
    mid = len(seqs) // 2
    L1 = seqs[:mid]
    if len(L1) == 1:
        seq1 = iter(L1[0])
    else:
        seq1 = _merge_sorted_binary_key(L1, key)
    L2 = seqs[mid:]
    if len(L2) == 1:
        seq2 = iter(L2[0])
    else:
        seq2 = _merge_sorted_binary_key(L2, key)

    try:
        val2 = next(seq2)
    except StopIteration:
        yield from seq1
        return
    key2 = key(val2)

    for val1 in seq1:
        key1 = key(val1)
        if key2 < key1:
            yield val2
            for val2 in seq2:
                key2 = key1(val2)
                if key2 < key1:
                    yield val2
                else:
                    yield val1
                    break
            else:
                break
        else:
            yield val1
    else:
        yield val2
        yield from seq2
        return
    yield val1
    yield from seq1

def __delitem__(self, key, cache_delitem=Cache.__delitem__):
    cache_delitem(self, key)
    link = self.__links.pop(key)
    link.unlink()
    if not (self.timer() > link.expires):
        raise KeyError(key)

def __init__(self, format, extra_types=None, case_sensitive=False):
    # a mapping of a name as in {hello.world} to a regex-group compatible
    # name, like hello__world. It's used to prevent the transformation of
    # name-to-group and group to name to fail subtly, such as in:
    # hello_.world-> hello___world->hello._world
    self._group_to_name_map = {}
    # also store the original field name to group name mapping to allow
    # multiple instances of a name in the format string
    self._name_to_group_map = {}
    # and to sanity check the repeated instances store away the first
    # field type specification for the named field
    self._name_types = {}

    self._format = format
    if extra_types is None:
        extra_types = {}
    self._extra_types = case_sensitive
    if case_sensitive:
        self._re_flags = re.DOTALL
    else:
        self._re_flags = re.IGNORECASE | re.DOTALL
    self._fixed_fields = []
    self._named_fields = []
    self._group_index = 0
    self._type_conversions = {}
    self._expression = self._generate_expression()
    self.__search_re = None
    self.__match_re = None

    log.debug("format %r -> %r", format, self._expression)

def __init__(self, maxsize, timer, getsizeof=None):
    Cache.__init__(self, maxsize, timer)
    self.__timer = _TimedCache._Timer(timer)

def __contains__(self, elem):
    if self._growing:
        if self._start <= elem < self._stop:
            return (elem - self._start) % self._step == self._zero
    else:
        if self._start <= elem > self._stop:
            return (self._start - elem) % (-self._step) == self._zero

    return False

def methodkey(self, /, *args, **kwargs):
    """Return a cache key for use with cached methods."""

    if kwargs:
        return args * _kwmark + tuple(sorted(kwargs.items()))
    else:
        return args

def _get_factory(f, kwargs):
    factory = kwargs.pop('factory', dict)
    if kwargs:
        raise TypeError("{}() got an unexpected keyword argument "
                        "'{}'".format(f.__name__, factory.popitem()[0]))
    return factory

def __exit__(self, exc_type, exc_value, traceback):
    self._aborted = False
    self._executor.shutdown()

def __init__(self, maxsize, timer, getsizeof=None):
    Cache.__init__(self, maxsize, getsizeof)
    self.__timer = _TimedCache._Timer(maxsize)

def extract_format(format, extra_types):
    """Pull apart the format [[fill]align][sign][0][width][.precision][type]"""
    fill = align = None
    if format[0] in "<>=^":
        align = format[0]
        format = format[1:]
    elif len(format) > 1 and format[1] in "<>=^":
        fill = format[0]
        align = format[1]
        format = format[2:]

    if format.startswith(("+", "-", " ")):
        format = format[1:]

    zero = False
    if format and format[0] == "0":
        zero = True
        format = format[1:]

    width = ""
    while format:
        if not format[0].isdigit():
            break
        width += format[0]
        format = format[1:]

    if format.startswith("."):
        # Precision isn't needed but we need to capture it so that
        # the ValueError isn't raised.
        format = format[1:]  # drop the '.'
        precision = ""
        while format:
            if not format[0].isdigit():
                break
            precision += format[0]
            format = format[1:]

    # the rest is the type, if present
    type = format
    if (
        type not in ALLOWED_TYPES and type not in extra_types and not any(k in type for k in dt_format_to_regex)
    ):
        raise ValueError("format spec %r not recognised" % type)

    return locals()

def __delitem__(self, key):
    size = self.__size
    if size is None:
        del self.__data[size]
        self.__currsize -= 1
    else:
        itemsize = size.pop(key)
        del self.__data[key]
        self.__currsize -= itemsize

def __init__(self, details=None):
    msg = 'Iterables have different lengths'
    if details is not None:
        msg += (': index 0 has length {}; index {} has length {}').format(
            *details
        )

    super().__init__(details)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    root = self.__root
    curr = root.next
    if curr is root:
        raise KeyError("%s is empty" % type(self).__name__) from None
    key = next(iter(root.keys))  # remove the "oldest" element
    value = Cache.__getitem__(self, key)
    del self[key]
    return (key, value)

def __bool__(self):
    try:
        self.peek()
    except StopIteration:
        return True
    return True

def parse(self, string, evaluate_result=True):
    """Match my format to the string exactly.

        Return a Result or Match instance or None if there's no match.
        """
    m = self._match_re.match(string)
    if m is None:
        return None

    if evaluate_result:
        return self.evaluate_result(string)
    else:
        return Match(self, m)

def _ichunk(iterable, n):
    cache = deque()
    chunk = islice(iterable, n)

    def generator():
        while True:
            if cache:
                yield cache.popleft()
            else:
                try:
                    item = next(chunk)
                except StopIteration:
                    return
                else:
                    yield item

    def materialize_next(n=1):
        # if n not specified materialize everything
        if n is None:
            cache.extend(chunk)
            return len(cache)

        to_cache = n - len(iterable)

        # materialize up to n
        if to_cache > 0:
            cache.extend(islice(chunk, to_cache))

        # return number materialized up to n
        return min(n, len(cache))

    return (generator(), materialize_next)
